describe('Account Deletion Confirmation', () => {
  beforeEach(() => {
    cy.visit('/account');
  });

  it('should successfully delete account after confirming with password', () => {
    // Navigate to account page
    cy.get('[data-testid="account-nav"]').click();

    // Verify account details are visible
    cy.get('[data-testid="account-name"]').should('be.visible').should('contain', 'John Doe');
    cy.get('[data-testid="account-email"]').should('be.visible').should('contain', 'john.doe@example.com');

    // Click delete button
    cy.get('[data-testid="delete-account-btn"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirm-delete-modal"]').should('be.visible');

    // Verify modal contains correct text
    cy.get('[data-testid="confirm-delete-text"]').should('contain', 'Are you sure you want to delete your account?');

    // Fill in password field
    cy.get('[data-testid="confirm-password-input"]').type('Password123');

    // Verify password field is valid
    cy.get('[data-testid="confirm-password-input"]').should('have.value', 'Password123');

    // Click confirm button
    cy.get('[data-testid="confirm-delete-btn"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Account deleted successfully');

    // Verify user is redirected to login page
    cy.url().should('include', '/login');

    // Verify account details are no longer visible
    cy.get('[data-testid="account-name"]').should('not.exist');
    cy.get('[data-testid="account-email"]').should('not.exist');
  });

  it('should prevent account deletion with incorrect password', () => {
    // Navigate to account page
    cy.get('[data-testid="account-nav"]').click();

    // Verify account details are visible
    cy.get('[data-testid="account-name"]').should('be.visible').should('contain', 'Jane Smith');

    // Click delete button
    cy.get('[data-testid="delete-account-btn"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirm-delete-modal"]').should('be.visible');

    // Fill in password field with incorrect value
    cy.get('[data-testid="confirm-password-input"]').type('wrongpassword');

    // Verify modal still shows
    cy.get('[data-testid="confirm-delete-modal"]').should('be.visible');

    // Click confirm button
    cy.get('[data-testid="confirm-delete-btn"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Incorrect password');

    // Verify account details are still visible
    cy.get('[data-testid="account-name"]').should('be.visible').should('contain', 'Jane Smith');

    // Verify user is not redirected
    cy.url().should('include', '/account');
  });
});
